#!/usr/bin/env bash
# Generates (default mode) or verifies offline (--check) the v0.1 save-envelope
# corpus in fixtures/save-envelope-v1.
#
# Generate mode is a ONE-TIME maintainer step on macOS arm64 (the v0.1.2 player
# session uses CommonCrypto, so it is not a CI leg). It builds the frozen v0.1.2
# tag in a scratch directory and drives the released player_session_save_battery
# writer, so the committed envelopes are bytes the released writer really
# produced. They must never be hand-assembled or regenerated by the current
# writer: they are the evidence that old saves still load (CART-06).
#
# Usage: generate-save-envelope-v1.sh [--check]
#        generate-save-envelope-v1.sh --generate [OUT_DIR]   (default mode)
# Generate mode needs the SDL3 3.4.18 prefix that verify-phase3-player.sh
# builds at build/phase3-player/prefix (archive digest recorded below).
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd -P)"
FIXTURE_DIR="${ROOT_DIR}/fixtures/save-envelope-v1"
TAG="v0.1.2"
TAG_COMMIT="3fa00be9d8ad8ca12a9bc4672d4851db1eabfa8e"
SDL_VERSION="3.4.18"
SDL_SHA256="9c75cf16330322c217dedd2e0609f1124f1b54b8633e763467b4684d0f4334a3"
SDL_PREFIX="${ROOT_DIR}/build/phase3-player/prefix"

fail() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }

# Recipe ROM, RAM pattern and envelope decoding live in one Python program so
# generate and check can never disagree. The envelope is decoded field by field
# at the v0.1 byte offsets; no C struct layout is assumed.
PY_LIB='
import hashlib, json, struct, sys, zlib

RECIPES = {
    "mbc1-8k.gbb":  {"title": "GBBV1CORPUS8K",  "type": 3, "rom_code": 0, "ram_code": 2, "size_bytes": 32768, "ram_size": 8192},
    "mbc1-32k.gbb": {"title": "GBBV1CORPUS32K", "type": 3, "rom_code": 0, "ram_code": 3, "size_bytes": 32768, "ram_size": 32768},
}
PATTERN = "byte i = (uint8_t)(i * 37 + 0x31)"

def build_rom(r):
    rom = bytearray(r["size_bytes"])
    rom[0x134:0x134 + len(r["title"])] = r["title"].encode("ascii")
    rom[0x147], rom[0x148], rom[0x149] = r["type"], r["rom_code"], r["ram_code"]
    c = 0
    for i in range(0x134, 0x14D):
        c = (c - rom[i] - 1) & 0xFF
    rom[0x14D] = c
    return bytes(rom)

def ram_pattern(n):
    return bytes((i * 37 + 0x31) & 0xFF for i in range(n))

def sha(b):
    return hashlib.sha256(b).hexdigest()
'

py() { python3 -I -c "${PY_LIB}
$1" "${@:2}"; }

check() {
  [[ -f "${FIXTURE_DIR}/manifest.json" ]] || { echo "check=fail:manifest missing"; exit 1; }
  py '
import os
fx = sys.argv[1]
def bad(msg):
    print("check=fail:" + msg); sys.exit(1)
m = json.load(open(os.path.join(fx, "manifest.json")))
if m.get("id") != "save-envelope-v1" or m.get("tag") != "v0.1.2":
    bad("manifest identity")
if m.get("tag_commit") != sys.argv[2]:
    bad("tag commit")
if m.get("sdl", {}).get("archive_sha256") != sys.argv[3]:
    bad("sdl digest")
entries = {e["file"]: e for e in m["envelopes"]}
for name, r in RECIPES.items():
    if name not in entries:
        continue
    e = entries[name]
    data = open(os.path.join(fx, name), "rb").read()
    if len(data) != 51 + r["ram_size"] or e["size_bytes"] != len(data):
        bad(name + ": size")
    if sha(data) != e["sha256"]:
        bad(name + ": manifest digest")
    if data[0:8] != b"GBBBSAVE":
        bad(name + ": magic")
    if struct.unpack_from("<H", data, 8)[0] != 1:
        bad(name + ": version")
    rom_sha = sha(build_rom(r))
    if rom_sha != e["rom_sha256"] or data[10:42].hex() != rom_sha:
        bad(name + ": rom sha256")
    if data[42] != 0x03:
        bad(name + ": type")
    if struct.unpack_from("<I", data, 43)[0] != r["ram_size"]:
        bad(name + ": ram length")
    payload = data[51:]
    if struct.unpack_from("<I", data, 47)[0] != (zlib.crc32(payload) & 0xFFFFFFFF):
        bad(name + ": crc32")
    if payload != ram_pattern(r["ram_size"]):
        bad(name + ": payload pattern")
    if e["rom_recipe"]["title"] != r["title"] or e["rom_recipe"]["ram_code"] != r["ram_code"]:
        bad(name + ": recipe")
if not entries:
    bad("no envelopes")
print("check=pass")
' "${FIXTURE_DIR}" "${TAG_COMMIT}" "${SDL_SHA256}"
}

generate() {
  local out_dir=${1:-}
  [[ "$(uname -sm)" == "Darwin arm64" ]] || fail 'generate mode requires macOS arm64'
  [[ -f "${SDL_PREFIX}/lib/libSDL3.dylib" ]] ||
    fail "SDL3 ${SDL_VERSION} prefix missing at build/phase3-player/prefix; build it with verify-phase3-player.sh first"
  [[ "$(git -C "$ROOT_DIR" rev-parse "${TAG}^{commit}")" == "$TAG_COMMIT" ]] ||
    fail "tag ${TAG} does not resolve to ${TAG_COMMIT}"
  work=$(mktemp -d)
  trap 'rm -rf -- "$work"' EXIT
  mkdir -p "$work/tree" "$work/pref" "$work/out"
  git -C "$ROOT_DIR" archive "$TAG" | tar -x -C "$work/tree"

  cat > "$work/driver.c" <<'EOC'
#include "session.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
/* Throwaway driver: runs the released v0.1.2 writer path end to end. */
int main(int argc, char **argv) {
    if (argc != 4) return 2;
    const char *rom_path = argv[1], *pref = argv[2], *out_path = argv[3];
    player_session_test_set_pref_path(pref);
    gbb_instance *machine = NULL;
    char *owned = NULL;
    char err[256];
    player_save_identity id;
    int lock_fd = -1;
    if (gbb_create(GBB_PROFILE_DMG_CPU_B, &machine) != GBB_OK) return 3;
    if (!player_session_replace_rom(machine, &owned, rom_path, &id, err, sizeof err)) return 4;
    if (player_session_lock_battery(&id, &lock_fd, err, sizeof err) != PLAYER_SESSION_LOCK_ACQUIRED) return 5;
    if (!player_session_load_battery(machine, &id, err, sizeof err)) return 6;
    size_t n = 0;
    if (gbb_battery_size(machine, &n) != GBB_OK || n > 32768u) return 7;
    uint8_t ram[32768];
    for (size_t i = 0; i < n; ++i) ram[i] = (uint8_t)(i * 37u + 0x31u);
    if (gbb_import_battery(machine, ram, n) != GBB_OK) return 8;
    uint64_t generation = 0;
    if (gbb_battery_generation(machine, &generation) != GBB_OK) return 9;
    if (!player_session_save_battery(machine, &id, err, sizeof err)) return 10;
    char *saved = player_session_test_battery_file_path(&id);
    if (saved == NULL) return 11;
    FILE *in = fopen(saved, "rb"), *out = fopen(out_path, "wb");
    if (in == NULL || out == NULL) return 12;
    uint8_t buf[40000];
    size_t got = fread(buf, 1, sizeof buf, in);
    if (fwrite(buf, 1, got, out) != got || fclose(out) != 0) return 13;
    fclose(in);
    printf("generation=%llu\n", (unsigned long long)generation);
    player_session_unlock_battery(&lock_fd);
    free(saved); free(owned); gbb_destroy(machine);
    return 0;
}
EOC
  local t="$work/tree"
  cc -std=c17 -O2 -DGBB_PLAYER_SESSION_TESTING \
     -DGBB_BUILD_REVISION=\"${TAG_COMMIT}\" -DGBB_BUILD_QUALIFIED=1 \
     -I"$t/include" -I"$t/src/player" -I"${SDL_PREFIX}/include" \
     "$work/driver.c" "$t/src/player/session.c" "$t/src/core/gabbaboy.c" \
     -L"${SDL_PREFIX}/lib" -lSDL3 -Wl,-rpath,"${SDL_PREFIX}/lib" \
     -o "$work/driver"

  local name
  for name in mbc1-8k.gbb mbc1-32k.gbb; do
    py 'open(sys.argv[2], "wb").write(build_rom(RECIPES[sys.argv[1]]))' "$name" "$work/$name.rom"
    rm -rf -- "$work/pref"; mkdir -p "$work/pref"
    "$work/driver" "$work/$name.rom" "$work/pref" "$work/out/$name" > "$work/out/$name.gen"
  done
  if [[ -n "$out_dir" ]]; then
    mkdir -p "$out_dir"
    cp "$work"/out/*.gbb "$out_dir/"
    cp "$work"/out/*.gen "$out_dir/"
    return
  fi
  mkdir -p "$FIXTURE_DIR"
  cp "$work"/out/*.gbb "$FIXTURE_DIR/"
  py '
import os, subprocess, platform
fx, work, tag, commit, sdl_v, sdl_sha, cc, plat = sys.argv[1:9]
envs = []
for name, r in RECIPES.items():
    p = os.path.join(fx, name)
    if not os.path.exists(p):
        continue
    gen = int(open(os.path.join(work, "out", name + ".gen")).read().split("=")[1])
    data = open(p, "rb").read()
    envs.append({"file": name,
        "rom_recipe": {"title": r["title"], "type": "0x03", "rom_code": r["rom_code"],
                       "ram_code": r["ram_code"], "size_bytes": r["size_bytes"],
                       "ram_pattern": PATTERN,
                       "layout": "zero-filled; title at 0x134; 0x147/0x148/0x149 as given; header checksum at 0x14D over 0x134..0x14C"},
        "rom_sha256": sha(build_rom(r)), "generation": gen,
        "size_bytes": len(data), "sha256": sha(data)})
m = {"id": "save-envelope-v1", "tag": tag, "tag_commit": commit,
     "writer": "src/player/session.c player_session_save_battery at v0.1.2",
     "sdl": {"version": sdl_v, "archive_sha256": sdl_sha},
     "compiler": cc, "platform": plat,
     "license": "MIT; see LICENSE.txt and repository LICENSE",
     "envelopes": envs}
open(os.path.join(fx, "manifest.json"), "w").write(json.dumps(m, indent=2) + "\n")
' "$FIXTURE_DIR" "$work" "$TAG" "$TAG_COMMIT" "$SDL_VERSION" "$SDL_SHA256" \
    "$(cc --version | head -n 1)" "$(uname -sm)"
}

case "${1:---generate}" in
  --check) check ;;
  --generate) generate "${2:-}" ;;
  *) fail "usage: $0 [--check | --generate [OUT_DIR]]" ;;
esac
